import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for optimized BatchNorm
batchnorm_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void batchnorm_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    float epsilon,
    float* __restrict__ output,
    int num_elements,
    int C, int H, int W) {

    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    const int c = (idx / (H * W)) % C;

    const float inv_std = rsqrtf(running_var[c] + epsilon);
    const float normalized = (input[idx] - running_mean[c]) * inv_std;
    output[idx] = normalized * gamma[c] + beta[c];
}

torch::Tensor batchnorm_forward_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    float epsilon) {

    auto output = torch::empty_like(input);
    const int num_elements = input.numel();
    const int C = gamma.size(0);
    const int H = input.size(2);
    const int W = input.size(3);

    const int block_size = 256;
    const int grid_size = (num_elements + block_size - 1) / block_size;

    batchnorm_forward_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        epsilon,
        output.data_ptr<float>(),
        num_elements,
        C, H, W);

    return output;
}
"""

batchnorm_cpp_source = "torch::Tensor batchnorm_forward_cuda(torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, float);"

batchnorm_ext = load_inline(
    name="batchnorm_ext",
    cpp_sources=batchnorm_cpp_source,
    cuda_sources=batchnorm_source,
    functions=["batchnorm_forward_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, num_features: int, eps=1e-5):
        super().__init__()
        self.eps = eps
        self.gamma = nn.Parameter(torch.ones(num_features))
        self.beta = nn.Parameter(torch.zeros(num_features))
        self.register_buffer('running_mean', torch.zeros(num_features))
        self.register_buffer('running_var', torch.ones(num_features))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return batchnorm_ext.batchnorm_forward_cuda(
            x.contiguous(),
            self.gamma,
            self.beta,
            self.running_mean,
            self.running_var,
            self.eps
        )
